// client-ordering · кейсы co-05, co-06, co-07 (.qa/tests/client-ordering/) — מלאי, מינימום הזמנה, שיתוף
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/buyer.json') });

// Тестовые данные staging (2026-10-03). Если пересоздадут — взять в каталоге buyer любой товар в наличии
// и товар с min_order_qty > 1 (у admin в карточке товара).
const IN_STOCK = { id: '340b7b2b-e022-4f3b-a6f0-f9a3dc8ecfe8', name: 'מצית קליפט' };
const MIN_QTY = { id: '394d4d94-90ca-42cc-83fb-5e8d3c0ae56a', name: 'אל די אדום קצר', min: 2 };

const shekels = (s: string) => Number(s.replace(/[^\d.]/g, ''));

test.describe('client-ordering — כרטיס מוצר', () => {
  test.skip('רק «במלאי» / «אזל», בלי «כמות מוגבלת»; מוצר שאזל לא ניתן להוספה #6a748c9a @prod-safe', { annotation: { type: 'skip', description: 'временно отключено 26.10 по просьбе клиента (#e7e338, лимит остатка снят); вернуть вместе с #e02e48 — knowledge/stock-logic-snapshot-2026-10-26.md §5' } }, async ({ page }) => {
    await page.goto('/shop');
    await expect(page.locator('article').first()).toBeVisible();
    await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));
    await page.waitForTimeout(800);
    await expect(page.getByText('כמות מוגבלת')).toHaveCount(0);
    const soldOut = page.locator('article').filter({ hasText: 'אזל' });
    const n = await soldOut.count();
    for (let i = 0; i < Math.min(n, 20); i++) {
      await expect(soldOut.nth(i).getByRole('button', { name: /^הוספה לעגלה/ })).toHaveCount(0);
    }

    await page.goto(`/shop/p/${IN_STOCK.id}`);
    await expect(page.getByRole('heading', { level: 1, name: IN_STOCK.name })).toBeVisible();
    await expect(page.getByText('במלאי', { exact: true })).toBeVisible();
    await expect(page.getByRole('button', { name: /^הוסף לעגלה/ })).toBeEnabled();
    await expect(page.getByText('כמות מוגבלת')).toHaveCount(0);
  });

  test.skip('מוצר שאזל — «אזל מהמלאי», כפתורים חסומים #6a748c9a @prod-safe', { annotation: { type: 'skip', description: 'временно отключено 26.10 по просьбе клиента (#e7e338, лимит остатка снят); вернуть вместе с #e02e48 — knowledge/stock-logic-snapshot-2026-10-26.md §5' } }, async ({ page }) => {
    await page.goto(`/shop/p/${MIN_QTY.id}`);
    await expect(page.getByRole('heading', { level: 1, name: MIN_QTY.name })).toBeVisible();
    const soldOut = page.getByRole('button', { name: 'המוצר אזל מהמלאי' });
    test.skip(!(await soldOut.isVisible()), 'товар сейчас в наличии — проверка «אזל» неприменима');
    await expect(page.getByText('אזל מהמלאי', { exact: true })).toBeVisible();
    await expect(soldOut).toBeDisabled();
    await expect(page.getByRole('button', { name: `הוספת יחידה — ${MIN_QTY.name}` })).toBeDisabled();
  });

  test('מינימום הזמנה נאכף והסכום מוצג עבור המינימום #6a788a95 @desktop @prod-safe', async ({ page }) => {
    // Карточка в каталоге: «מינימום הזמנה: 2» и «סה״כ» = 2 × цена.
    await page.goto('/shop');
    await page.getByRole('searchbox', { name: 'חיפוש מוצר' }).fill(MIN_QTY.name);
    const card = page.locator('article').filter({ hasText: MIN_QTY.name }).first();
    await expect(card).toContainText(`מינימום הזמנה: ${MIN_QTY.min}`);
    const text = await card.innerText();
    const price = shekels(text.match(/₪[\d,.]+/)![0]);
    const total = shekels(text.match(/סה״כ\s*₪[\d,.]+/)![0]);
    expect(total).toBeCloseTo(price * MIN_QTY.min, 2);

    // Страница товара: счётчик стартует с минимума.
    await page.goto(`/shop/p/${MIN_QTY.id}`);
    await expect(page.getByText(`מינימום הזמנה: ${MIN_QTY.min}`)).toBeVisible();
    const minus = page.getByRole('button', { name: `הפחתת יחידה — ${MIN_QTY.name}` });
    const stepper = minus.locator('..');
    await expect(stepper).toContainText(String(MIN_QTY.min));

    // Нельзя уменьшить ниже минимума (проверяемо, только когда товар в наличии).
    const add = page.getByRole('button', { name: /^הוסף לעגלה/ });
    test.skip(!(await add.isVisible()), 'товар с минимумом сейчас «אזל מהמלאי» — нужен товар в наличии с min_order_qty > 1');
    await expect(minus).toBeDisabled();
  });

  test('כפתור «שיתוף המוצר» בכרטיס המוצר משתף שם וקישור (Web Share) #6a672659 @desktop @prod-safe', async ({ page }) => {
    await page.addInitScript(() => {
      (window as any).__shared = [];
      Object.defineProperty(navigator, 'share', { configurable: true, value: async (d: unknown) => { (window as any).__shared.push(d); } });
    });
    await page.goto(`/shop/p/${IN_STOCK.id}`);
    await expect(page.getByRole('button', { name: 'חזרה' })).toBeVisible();
    await page.getByRole('button', { name: 'שיתוף המוצר' }).click();
    const shared = await page.evaluate(() => (window as any).__shared);
    expect(shared).toHaveLength(1);
    expect(shared[0].title).toBe(IN_STOCK.name);
    expect(shared[0].url).toContain(`/shop/p/${IN_STOCK.id}`);
  });

  test('שיתוף ללא Web Share API — העתקת קישור #6a672659 @desktop @prod-safe', async ({ page }) => {
    await page.addInitScript(() => {
      (window as any).__clip = [];
      Object.defineProperty(navigator, 'share', { configurable: true, value: undefined });
      Object.defineProperty(navigator, 'clipboard', {
        configurable: true,
        value: { writeText: async (t: string) => { (window as any).__clip.push(t); } },
      });
    });
    await page.goto(`/shop/p/${IN_STOCK.id}`);
    await page.getByRole('button', { name: 'שיתוף המוצר' }).click();
    await expect(page.getByText('הקישור הועתק')).toBeVisible();
    const clip = await page.evaluate(() => (window as any).__clip);
    expect(clip[0]).toContain(`/shop/p/${IN_STOCK.id}`);
  });
});
